package com.clouddocs.auth;
import org.junit.jupiter.api.*;import org.springframework.mock.web.MockMultipartFile;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.security.access.AccessDeniedException;
import com.clouddocs.audit.AuditLogService;import java.util.*;import java.io.*;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class AvatarServiceTest {
 final UserRepository users=mock(UserRepository.class);final UserAvatarRepository avatars=mock(UserAvatarRepository.class);final AuditLogService audit=mock(AuditLogService.class);final AvatarService service=new AvatarService(users,avatars,audit);User user;
 @BeforeEach void setup(){user=new User();user.setUsername("worker");user.setFullName("Test User");ReflectionTestUtils.setField(user,"id",2L);when(users.findByUsernameIgnoreCase("worker")).thenReturn(Optional.of(user));when(users.findById(2L)).thenReturn(Optional.of(user));when(users.findForStorageUpdate(2L)).thenReturn(Optional.of(user));}
 MockMultipartFile image(String format)throws Exception{var image=new BufferedImage(400,200,BufferedImage.TYPE_INT_RGB);image.setRGB(200,100,0xff0000);var bytes=new ByteArrayOutputStream();ImageIO.write(image,format,bytes);return new MockMultipartFile("file","avatar."+format,"image/"+format,bytes.toByteArray());}
 @Test void convertsUploadedImageToSquarePngAndStoresOwnAvatar()throws Exception{service.upload("worker",image("jpg"));var captor=org.mockito.ArgumentCaptor.forClass(UserAvatar.class);verify(avatars).saveAndFlush(captor.capture());assertEquals(2L,captor.getValue().getUserId());var saved=ImageIO.read(new ByteArrayInputStream(captor.getValue().getData()));assertEquals(256,saved.getWidth());assertEquals(256,saved.getHeight());assertNotNull(user.getAvatarUpdatedAt());verify(audit).logInTransaction(eq("worker"),eq("UPDATE_AVATAR"),isNull(),eq(2L),anyString());}
 @Test void acceptsImageOverTwoMbWhenBelowFiveMb()throws Exception{var original=image("png");byte[] padded=java.util.Arrays.copyOf(original.getBytes(),3*1024*1024);assertTrue(service.normalize(new MockMultipartFile("file","large.png","image/png",padded)).length>0);}
 @Test void acceptsPng()throws Exception{assertTrue(service.normalize(image("png")).length>0);}
 @Test void rejectsSvgTextEmptyAndOversizedFiles(){for(byte[] value:List.of(new byte[0],"<svg onload='alert(1)'/>".getBytes(),new byte[5*1024*1024+1]))assertThrows(IllegalArgumentException.class,()->service.normalize(new MockMultipartFile("file","fake.png","image/png",value)));verifyNoInteractions(avatars);}
 @Test void lockedUserCannotChangeOrReadAvatar()throws Exception{user.setStatus("LOCKED");assertThrows(AccessDeniedException.class,()->service.upload("worker",image("png")));assertThrows(AccessDeniedException.class,()->service.delete("worker"));assertThrows(AccessDeniedException.class,()->service.read("worker",2L));verifyNoInteractions(avatars,audit);}
 @Test void deleteRemovesImageAndFallsBackToInitials(){UserAvatar avatar=new UserAvatar();avatar.setUserId(2L);when(avatars.findById(2L)).thenReturn(Optional.of(avatar));user.setAvatarUpdatedAt(java.time.Instant.now());service.delete("worker");verify(avatars).delete(avatar);assertNull(user.getAvatarUpdatedAt());verify(users).saveAndFlush(user);}
 @Test void missingAvatarReturns404(){var ex=assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.read("worker",2L));assertEquals(404,ex.getStatusCode().value());}
}
